const lead = $input.first().json.body || {};
const recipient = lead.recipient_email || 'partner@enterprise.io';
const company = lead.company || 'Enterprise Partner';
const valueProp = lead.value_prop || 'Autonomous workflow automation & AI orchestration';

const draft = `# Outreach Proposal to ${company}

To: ${recipient}
Subject: Autonomous Execution & Operational Leverage for ${company}

Hi team,

I reviewed ${company}'s current trajectory and wanted to share how our OMEGA autonomous workflows can accelerate your operations by over 10x with zero manual overhead.

Key capabilities:
- Fully self-hosted Zapier & n8n workflow engine
- Instant webhook routing and LangChain AI agent integration
- Automated lead ingestion and real-time reconciliation

Would you be open to a 10-minute briefing this week?

Best regards,
Autonomous Enterprise Systems`;

return [{
  json: {
    status: 'DRAFT_GENERATED',
    recipient: recipient,
    company: company,
    draft_preview: draft
  }
}];

// Enrich and standardize payload
const item = $input.first().json;
return [{
  json: {
    status: 'PROCESSED',
    timestamp: new Date().toISOString(),
    recipient: item.body.recipient_email,
    company: item.body.company || 'Unknown',
    source: item.body.source || 'OMEGA_PIPELINE',
    tracking_id: 'TRACK_' + Date.now()
  }
}];

// Log dropped items
const item = $input.first().json;
return [{
  json: {
    status: 'DROPPED',
    reason: 'Missing recipient email',
    raw_input: item
  }
}];

const res = $input.first().json;
const timestamp = new Date().toISOString();
return [{
  json: {
    system: 'OMEGA Automation Node',
    checked_at: timestamp,
    status: 'HEALTHY',
    details: res
  }
}];

const payload = $input.first().json.body || {};
const now = new Date();

return [{
  json: {
    event_id: 'EVT_' + now.getTime(),
    received_at: now.toISOString(),
    source: payload.source || 'EXTERNAL',
    action: payload.action || 'DEFAULT',
    payload: payload.data || payload,
    status: 'ACKNOWLEDGED'
  }
}];
